<template><section class="console-page"><PageHeading title="平台总览"><el-button size="small" icon="el-icon-refresh" :loading="loading" @click="load">检查</el-button></PageHeading><div class="status-strip"><div><span>平台服务</span><strong :class="healthTone" class="mono">{{ displayStatus }}</strong></div><div><span>健康检查</span><strong class="mono">/healthz</strong></div><div class="strip-source"><i class="status-dot" :class="healthTone" />{{ errorMessage || '已收到响应' }}</div></div><section class="data-panel"><PanelHeader title="平台工具" meta="真实接口" /><router-link v-for="tool in tools" :key="tool.path" :to="tool.path" class="tool-row"><i :class="tool.icon" /><div><strong>{{ tool.label }}</strong><span>{{ tool.description }}</span></div><span class="mono tool-path">{{ tool.path }}</span><i class="el-icon-arrow-right" /></router-link></section></section></template>
<script>
import PageHeading from '../../components/PageHeading.vue';
import PanelHeader from '../../components/PanelHeader.vue';
import { platformApi } from '../../api/platform';
export default { name: 'PlatformConsole', components: { PageHeading, PanelHeader }, data() { return { status: 'CHECKING', loading: false, errorMessage: '' }; }, computed: { healthTone() { return ['OK', 'HEALTHY', 'UP'].includes(this.status.toUpperCase()) ? 'success' : this.status === 'DOWN' ? 'danger' : 'warning'; }, displayStatus() { return ['OK', 'HEALTHY', 'UP'].includes(this.status.toUpperCase()) ? '正常' : this.status === 'DOWN' ? '不可用' : '检查中'; }, tools() { return [{ path: '/runtime', label: '运行状态', description: '查看剧集运行状态', icon: 'el-icon-refresh' }, { path: '/executions', label: '执行记录', description: '查询执行事实记录', icon: 'el-icon-s-operation' }, { path: '/traces', label: '链路追踪', description: '查询调用链路记录', icon: 'el-icon-share' }, { path: '/memory', label: '记忆检索', description: '检索经验和记忆', icon: 'el-icon-collection' }, { path: '/agents', label: '智能体', description: '查看智能体能力', icon: 'el-icon-user' }]; } }, created() { this.load(); }, methods: { load() { this.loading = true; this.errorMessage = ''; platformApi.health().then((body) => { this.status = body.status || 'UNKNOWN'; }).catch((error) => { this.status = 'DOWN'; this.errorMessage = error.message; }).finally(() => { this.loading = false; }); } } };
</script>
